WITH RankedPosts AS (SELECT P.Id AS PostId, P.Title, P.CreationDate, P.Score, P.AnswerCount, P.ViewCount, U.DisplayName AS Author, RANK() OVER (PARTITION BY P.PostTypeId ORDER BY P.Score DESC NULLS FIRST) AS PostRank, (SELECT COUNT(*) FROM Votes AS V WHERE V.PostId = P.Id AND V.VoteTypeId = 2) AS UpVoteCount FROM Posts AS P LEFT JOIN Users AS U ON P.OwnerUserId = U.Id WHERE P.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), TopPosts AS (SELECT PostId, Title, Score, UpVoteCount, ViewCount FROM RankedPosts WHERE PostRank <= 10), PostHistories AS (SELECT PH.PostId, COUNT(*) AS EditCount, MAX(PH.CreationDate) AS LastEditDate, GROUP_CONCAT(PHT.Name, ', ') AS EditTypes FROM PostHistory AS PH JOIN PostHistoryTypes AS PHT ON PH.PostHistoryTypeId = PHT.Id GROUP BY PH.PostId) SELECT TP.Title, TP.Score, TP.UpVoteCount, TP.ViewCount, COALESCE(PH.EditCount, 0) AS TotalEdits, PH.LastEditDate, PH.EditTypes FROM TopPosts AS TP LEFT JOIN PostHistories AS PH ON TP.PostId = PH.PostId ORDER BY TP.Score DESC NULLS FIRST, TP.ViewCount DESC NULLS FIRST